    <g class="sigil-rings sigil-rings-alt">
      <circle cx="100" cy="100" r="82" fill="none" stroke="${color}" stroke-opacity=".14" stroke-width=".6" stroke-dasharray="2 12"/>
    </g>
    ${ray.join('')}
    <g class="sigil-shape">
      <polygon points="${polygon(sides, 52, rot)}" fill="${color}" fill-opacity=".045" stroke="${color}" stroke-opacity=".6" stroke-width=".9"/>
      <polygon points="${polygon(sides, 31, -rot * 0.55 + 9)}" fill="none" stroke="${color}" stroke-opacity=".28" stroke-width=".7"/>
    </g>
    ${crown}
    <g class="sigil-eye">
      ${diamond}
      <path d="M57 100 Q100 75 143 100 Q100 125 57 100 Z" fill="${color}" fill-opacity=".055" stroke="${color}" stroke-opacity=".8" stroke-width="1.1"/>
      <circle cx="100" cy="100" r="8.5" fill="${color}" fill-opacity=".16" stroke="${color}" stroke-opacity=".85" stroke-width=".8"/>
      <circle cx="100" cy="100" r="3.2" fill="${color}"/>
      <circle cx="97.6" cy="97.4" r="1.1" fill="#fff" fill-opacity=".8"/>
    </g>
    <circle cx="100" cy="100" r="96" fill="none" stroke="${color}" stroke-opacity=".12" stroke-width=".6"/>
  </svg>`;
}

function bossSigil(boss, opts) {
