async (page) => {
  const log = [];
  const modalOpen = () => page.evaluate(() => document.querySelector('#modal').getAttribute('aria-hidden') === 'false');
  const screenshot = (name) => page.screenshot({ path: 'screenshots/' + name });

  await page.goto('http://localhost:3000/?v=e2e1');
  await page.click('#btn-start');
  await page.waitForTimeout(500);
  await page.click('text=I UNDERSTAND');
  await page.waitForTimeout(400);

  // Challenge Ember, then yield immediately.
  await page.click('[data-fight="ember"]');
  await page.waitForTimeout(1800);
  await page.click('#btn-yield');
  await page.waitForTimeout(350);
  await screenshot('qa-yield-confirm.png');
  await page.click('[data-act="yield-confirm"]');
  await page.waitForTimeout(1800);
  log.push({ defeatModal: await modalOpen(), modalText: (await page.locator('#modalBody').innerText()).slice(0, 260) });
  await screenshot('qa-defeat-gift.png');
  await page.click('[data-act="ladder"]');
  await page.waitForTimeout(500);
  log.push({ tagged: (await page.locator('#ladderList').innerText()).includes('STOLEN'), slots: await page.locator('#loadoutSlots .slot.filled').count() });
  await screenshot('qa-ladder-after-steal.png');

  // Rematch and win with Cinder.
  await page.click('[data-fight="ember"]');
  await page.waitForTimeout(1900);
  let guard = 0;
  while (guard++ < 40 && !(await modalOpen())) {
    const action = await page.evaluate(() => {
      const cinder = document.querySelector('[data-action="cinder"]');
      const strike = document.querySelector('[data-action="strike"]');
      const end = document.querySelector('#btn-end');
      const pips = [...document.querySelectorAll('.pip.full')].length;
      return {
        cinder: !!cinder && !cinder.disabled,
        strike: !!strike && !strike.disabled,
        pips,
        battle: document.querySelector('#screen-battle').classList.contains('active'),
        phaseText: document.querySelector('#turnBadge').textContent
      };
    });
    if (!action.battle) break;
    if (action.cinder) await page.click('[data-action="cinder"]');
    for (let i = 0; i < action.pips; i++) {
      const canStrike = await page.evaluate(() => {
        const s = document.querySelector('[data-action="strike"]');
        return !!s && !s.disabled;
      });
      if (!canStrike) break;
      await page.click('[data-action="strike"]');
      await page.waitForTimeout(80);
    }
    await page.waitForTimeout(150);
    if (await modalOpen()) break;
    await page.click('#btn-end');
    await page.waitForTimeout(1700);
  }
  log.push({ victoryModal: await modalOpen(), victoryText: (await page.locator('#modalBody').innerText()).slice(0, 320) });
  await screenshot('qa-victory-stolen.png');

  // Advance to Frost.
  const nextBtn = page.locator('#modalBody [data-act="start"]').first();
  log.push({ nextButton: await nextBtn.innerText().catch(() => null) });
  await nextBtn.click();
  await page.waitForTimeout(1700);
  log.push({ frostBattle: (await page.locator('#battleBossName').innerText()), screen: await page.evaluate(() => document.body.dataset.screen) });
  await screenshot('qa-mobile-battle-frost.png');
  return log;
}

