async (page) => {
  await page.goto('http://localhost:3000/?v=qa4#dev');
  await page.click('#btn-start');
  await page.waitForTimeout(400);
  await page.click('text=I UNDERSTAND');
  await page.waitForTimeout(300);
  await page.evaluate(() => {
    const s = window.__gc.state;
    s.stolen = new Set(['cinder']);
    s.equipped = ['cinder'];
    s.beaten = new Set(['ember']);
    window.__gc.renderLadder();
    window.__gc.startBattle('frost');
  });
  await page.waitForTimeout(2400);
  await page.evaluate(() => {
    window.__gc.showVictory(window.__gc.state.battle.boss);
  });
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'screenshots/qa-victory-unclaimed.png' });
  const info = await page.evaluate(() => ({
    ops: [...document.querySelectorAll('.modal-panel *')].filter((n) => n.children.length === 0 && n.textContent.trim()).map((n) => n.textContent.trim()).slice(0, 30),
    overflow: document.documentElement.scrollWidth > innerWidth,
    panel: document.querySelector('.modal-panel').getBoundingClientRect().toJSON()
  }));
  await page.locator('#modalBody .btn-primary').click();
  await page.waitForTimeout(1500);
  info.afterBoss = await page.locator('#battleBossName').innerText();
  return info;
}

